// ===== 바꿀 값은 이 노드에만 있습니다 =====
const cfg = {
  supabaseUrl: 'https://YOUR-PROJECT.supabase.co',
  geminiModel: 'gemini-3.8-flash',
  fallbackModel: 'gemini-flash-lite-latest',
  embeddingModel: 'gemini-embedding-001',
  embedDim: 768,
  matchCount: 12, // 종목으로 거른 검색 결과 수
  extraCount: 6, // 전체에서 더 찾는 결과 수
  maxSources: 14, // 답변에 넘길 최대 기록 수
  defaultDays: 90, // 질문에 기간이 없을 때 찾아볼 기간
  testQuestion: '최근 삼성전자 관련 주요 공시와 뉴스 흐름은?', // n8n에서 직접 실행할 때 쓰는 시험 질문
};

const input = $input.first().json || {};
const fromDiscord = !!(input.question && input.appId && input.token);
const question = String(input.question || cfg.testQuestion).trim().slice(0, 200);
const interpretText = `사용자가 자신의 투자 뉴스 지식베이스에 질문했다. 검색에 필요한 정보를 뽑아라.

질문: ${question}

출력: JSON 하나만.
{"companies": [질문의 중심 상장사 최대 3개. 국내는 {"name": 한국거래소 상장 종목명, "market": "KR"}, 미국은 {"name": 회사명, "market": "US", "ticker": 티커}. 없으면 빈 배열],
 "days": 질문에 기간이 있으면 일수(예: 최근 3개월 → 90, 이번 주 → 7), 없으면 null,
 "searchText": 의미 검색에 쓸 한국어 문장 (질문의 핵심 주제를 담아 한 문장)}`;

return [{
  json: {
    ...cfg,
    question,
    userDays: Number(input.days) || null,
    fromDiscord,
    followUrl: fromDiscord ? `https://discord.com/api/v10/webhooks/${input.appId}/${input.token}` : '',
    nowIso: new Date().toISOString(),
    interpretBody: { contents: [{ role: 'user', parts: [{ text: interpretText }] }], generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 2048 } },
  },
}];

// 회사명 비교용 키: 대문자, (주)·법인 접미사·기호 제거. 종목 사전과 게시 워크플로가 같은 규칙을 씀
function nameKey(s) {
  let t = String(s || '').toUpperCase();
  t = t.replace(/\(주\)|㈜|주식회사|\(유\)/g, ' ').replace(/&/g, ' AND ').replace(/\/[A-Z]{2}\/?\s*$/, ' ');
  t = t.replace(/[.,'’"()\-\/:;!]/g, ' ');
  const STOP = new Set(['INC', 'INCORPORATED', 'CORP', 'CORPORATION', 'CO', 'COMPANY', 'LTD', 'LIMITED', 'PLC', 'HOLDINGS', 'HOLDING', 'GROUP', 'THE', 'CLASS', 'A', 'B', 'C', 'SA', 'NV', 'AG', 'SE', 'LLC', 'LP', 'ADR', 'DE', 'TECHNOLOGIES', 'TECHNOLOGY']);
  return t.split(/\s+/).filter((w) => w && !STOP.has(w)).join('');
}
// Gemini 응답에서 글자만 꺼내고, JSON이면 읽어 줍니다.
function geminiText(j) {
  const parts = ((((j || {}).candidates || [])[0] || {}).content || {}).parts || [];
  return parts.filter((p) => !p.thought).map((p) => p.text || '').join('');
}
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}
// 질문 해석 정리. Gemini가 실패해도 질문 그대로 검색합니다.
const c = $('설정').first().json;
const o = parseJson(geminiText($input.first().json)) || {};
const companies = Array.isArray(o.companies) ? o.companies.filter((x) => x && x.name).slice(0, 3).map((x) => ({ name: String(x.name).slice(0, 40), market: x.market === 'US' ? 'US' : 'KR', ticker: x.ticker ? String(x.ticker).toUpperCase().trim() : '' })) : [];
const days = Math.max(1, Math.min(365, c.userDays || Number(o.days) || c.defaultDays));
return [{
  json: {
    companies,
    days,
    searchText: String(o.searchText || c.question).slice(0, 300),
    keys: companies.map((x) => nameKey(x.name)).filter(Boolean),
    tickers: companies.map((x) => x.ticker).filter(Boolean),
  },
}];

// 회사명 비교용 키: 대문자, (주)·법인 접미사·기호 제거. 종목 사전과 게시 워크플로가 같은 규칙을 씀
function nameKey(s) {
  let t = String(s || '').toUpperCase();
  t = t.replace(/\(주\)|㈜|주식회사|\(유\)/g, ' ').replace(/&/g, ' AND ').replace(/\/[A-Z]{2}\/?\s*$/, ' ');
  t = t.replace(/[.,'’"()\-\/:;!]/g, ' ');
  const STOP = new Set(['INC', 'INCORPORATED', 'CORP', 'CORPORATION', 'CO', 'COMPANY', 'LTD', 'LIMITED', 'PLC', 'HOLDINGS', 'HOLDING', 'GROUP', 'THE', 'CLASS', 'A', 'B', 'C', 'SA', 'NV', 'AG', 'SE', 'LLC', 'LP', 'ADR', 'DE', 'TECHNOLOGIES', 'TECHNOLOGY']);
  return t.split(/\s+/).filter((w) => w && !STOP.has(w)).join('');
}
// 회사를 종목 사전과 맞추고 검색 문장을 만듭니다.
const c = $('설정').first().json;
const q = $('해석 정리').first().json;
const ctx = $input.first().json || {};
const symbols = Array.isArray(ctx.symbols) ? ctx.symbols : [];
const targets = [];
for (const x of q.companies) {
  const hit = (x.market === 'US' && x.ticker && symbols.find((s) => s.market === 'US' && s.code === x.ticker))
    || symbols.find((s) => s.market === x.market && s.name_key === nameKey(x.name));
  if (hit && !targets.some((t) => t.code === hit.code)) targets.push({ market: hit.market, code: hit.code, name: hit.market === 'KR' ? hit.name : x.name });
}
const text = [q.searchText, ...targets.map((t) => t.name)].join(' / ');
return [{
  json: {
    targets,
    since: new Date(Date.now() - q.days * 86400_000).toISOString(),
    embedBody: { content: { parts: [{ text }] }, taskType: 'RETRIEVAL_QUERY', outputDimensionality: c.embedDim },
  },
}];

// 지식베이스 검색 요청 두 개: 종목으로 거른 검색 + 전체 검색 (종목이 없으면 둘 다 전체)
const c = $('설정').first().json;
const p = $('검색 준비').first().json;
const v = ((($input.first().json || {}).embedding) || {}).values || [];
if (v.length !== c.embedDim) return [{ json: { filtered: null, all: null } }];
const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
const vec = v.map((x) => Math.round((x / norm) * 1e6) / 1e6);
const codes = p.targets.map((t) => t.code);
const base = { query_embedding: vec, since: p.since, include_ai: true };
return [{
  json: {
    filtered: { ...base, match_count: c.matchCount, filter_codes: codes.length ? codes : null },
    all: { ...base, match_count: c.extraCount, filter_codes: null },
  },
}];

// 검색 결과를 합쳐 번호(S1…)를 붙이고 답변 요청을 만듭니다.
const c = $('설정').first().json;
const q = $('해석 정리').first().json;
const p = $('검색 준비').first().json;
const rows = [...$('지식베이스 검색 (종목)').all(), ...$('지식베이스 검색 (전체)').all()].map((i) => i.json).filter((r) => r && r.chunk_key && r.content);
const seen = new Set();
const uniq = rows.filter((r) => (seen.has(r.chunk_key) ? false : (seen.add(r.chunk_key), true)));
uniq.sort((a, b) => (b.similarity || 0) - (a.similarity || 0));
const top = uniq.slice(0, c.maxSources).sort((a, b) => String(a.published_at).localeCompare(String(b.published_at)));
const KIND = { news: '뉴스', filing: '공시', briefing: '시장 브리핑', research: '리서치', qa: '리서치 Q&A', data: '데이터' };
const day = (iso) => (iso ? new Date(Date.parse(iso) + 9 * 3600_000).toISOString().slice(0, 10) : '');
const sources = top.map((r, i) => ({
  id: `S${i + 1}`, date: day(r.published_at), kind: KIND[r.kind] || r.kind, source: r.source || '', url: r.url || '', isAI: !!r.is_ai,
  title: String(r.content).split('\n')[0].slice(0, 90), content: String(r.content).replace(/\s+/g, ' ').slice(0, 350),
}));
const recs = sources.map((s) => `[${s.id}] ${s.date} ${s.kind}${s.isAI ? ' (AI 해석)' : ''} · ${s.source} — ${s.content}`).join('\n');
const text = `너는 사용자의 투자 뉴스 지식베이스를 검색해 답하는 비서다. 아래 기록만 근거로 질문에 한국어로 답하라.

규칙
- 기록에 없는 내용은 추측하지 말고 없다고 말하라.
- 근거는 refs에 기록 번호(S1 등)로만 달고 URL은 쓰지 마라.
- "AI 해석" 기록은 과거 브리핑·리포트의 해석이다. 사실처럼 쓰지 말고 "당시 브리핑(리포트)은 ~로 봤다"처럼 구분하라.
- 시간 흐름을 묻는 질문이면 날짜 순서로 정리하라.
- 매수·매도 권유, 목표주가, 가격 예측은 하지 마라.

출력: JSON 하나만.
{"answer": [{"text": "문단 2~3문장", "refs": ["S1","S4"]}], "found": true 또는 false, "gaps": "기록이 부족한 점 한 문장, 없으면 빈 문자열"}

질문: ${c.question}
찾아본 기간: 최근 ${q.days}일${p.targets.length ? ` · 종목: ${p.targets.map((t) => `${t.name}(${t.code})`).join(', ')}` : ''}

기록
${recs || '(관련 기록 없음)'}`;
return [{
  json: {
    sources,
    answerBody: { contents: [{ role: 'user', parts: [{ text }] }], generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 4096 } },
  },
}];

// Gemini 응답에서 글자만 꺼내고, JSON이면 읽어 줍니다.
function geminiText(j) {
  const parts = ((((j || {}).candidates || [])[0] || {}).content || {}).parts || [];
  return parts.filter((p) => !p.thought).map((p) => p.text || '').join('');
}
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}
// Discord에 보낼 답변을 만듭니다. 근거 번호는 원문 링크로 바꿉니다.
const c = $('설정').first().json;
const q = $('해석 정리').first().json;
const p = $('검색 준비').first().json;
const { sources } = $('근거 정리').first().json;
const byId = Object.fromEntries(sources.map((s) => [s.id, s]));
let o = null;
for (const it of $input.all()) { o = parseJson(geminiText(it.json)); if (o && Array.isArray(o.answer)) break; o = null; }

const head = `**Q. ${c.question}**\n_최근 ${q.days}일${p.targets.length ? ` · ${p.targets.map((t) => t.name).join(', ')}` : ''} · 기록 ${sources.length}건 검색_`;
const link = (r) => { const s = byId[r]; return s && /^https?:/.test(s.url) ? `[${r}](<${s.url}>)` : r; };
let content;
if (!sources.length) {
  content = `${head}\n\n지식베이스에서 관련 기록을 찾지 못했습니다. 기간을 늘려(days 옵션) 다시 묻거나, /research로 새로 조사해 보세요.`;
} else if (!o) {
  content = `${head}\n\n⚠️ 답변을 만들지 못했습니다(Gemini 응답 오류). 잠시 뒤 다시 물어봐 주세요.`;
} else {
  const ids = new Set(sources.map((s) => s.id));
  const paras = o.answer.filter((x) => x && x.text).map((x) => {
    const refs = (Array.isArray(x.refs) ? x.refs : []).map(String).filter((r) => ids.has(r)).slice(0, 5);
    return `${String(x.text).replace(/https?:\/\/\S+/g, '').trim()}${refs.length ? ' ' + refs.map(link).join(' ') : ''}`;
  });
  const used = [...new Set(o.answer.flatMap((x) => (Array.isArray(x.refs) ? x.refs.map(String) : [])))].filter((r) => ids.has(r));
  const srcLines = used.slice(0, 8).map((r) => { const s = byId[r]; return `${r} ${s.date} ${s.kind}${s.isAI ? ' (AI 해석)' : ''} · ${s.title.slice(0, 60)}`; });
  content = [
    head,
    '',
    ...paras,
    o.gaps ? `\n_부족한 점: ${String(o.gaps).trim()}_` : '',
    srcLines.length ? `\n**근거**\n${srcLines.join('\n')}` : '',
  ].filter((x) => x !== '').join('\n');
}
if (content.length > 1990) content = content.slice(0, 1985) + '…';
return [{ json: { content } }];

// Discord에서 물어본 경우만 답변을 보냅니다 (n8n에서 직접 실행하면 "답변 완성" 출력에서 확인).
if (!$('설정').first().json.followUrl) return [];
return [{ json: $('답변 완성').first().json }];
